CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120),email text NOT NULL UNIQUE CHECK(email=lower(email) AND length(email)<=254),password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('OWNER','ADMIN','USER')),status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX users_role_status_idx ON users(role,status);
CREATE TABLE sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,token_hash bytea NOT NULL UNIQUE,csrf_hash bytea NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX sessions_user_id_idx ON sessions(user_id); CREATE INDEX sessions_expires_at_idx ON sessions(expires_at);
CREATE TABLE tools(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(trim(name)) BETWEEN 1 AND 120),description text NOT NULL DEFAULT '',icon text NOT NULL DEFAULT '',category text NOT NULL CHECK(length(trim(category)) BETWEEN 1 AND 80),route text NOT NULL UNIQUE CHECK(route LIKE '/%' AND route NOT LIKE '//%'),status text NOT NULL DEFAULT 'available' CHECK(status IN ('available','maintenance','unavailable')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX tools_category_status_idx ON tools(category,status);
CREATE TABLE permissions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL UNIQUE,description text NOT NULL DEFAULT '');
CREATE TABLE user_permissions(id bigserial PRIMARY KEY,user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,permission_id uuid NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,tool_id uuid REFERENCES tools(id) ON DELETE CASCADE); CREATE UNIQUE INDEX user_permissions_tool_unique ON user_permissions(user_id,permission_id,tool_id) WHERE tool_id IS NOT NULL; CREATE UNIQUE INDEX user_permissions_global_unique ON user_permissions(user_id,permission_id) WHERE tool_id IS NULL;
CREATE INDEX user_permissions_user_idx ON user_permissions(user_id);
CREATE TABLE security_events(id bigserial PRIMARY KEY,user_id uuid REFERENCES users(id) ON DELETE SET NULL,event text NOT NULL,ip inet,details jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX security_events_created_at_idx ON security_events(created_at);
CREATE TABLE rate_limits(key text PRIMARY KEY,window_started_at timestamptz NOT NULL,attempts integer NOT NULL CHECK(attempts>=0),updated_at timestamptz NOT NULL DEFAULT now());
